namespace sh_double {

/**
 * @brief Orient polygon CCW in place (reverse if clockwise signed area < 0).
 */
inline void to_ccw(std::vector<std::array<double, 2>>& v) {
    double a = 0.0;
    const int n = static_cast<int>(v.size());
    for (int i = 0; i < n; ++i) {
        const auto& p = v[i];
        const auto& q = v[(i + 1) % n];
        a += p[0] * q[1] - q[0] * p[1];
    }
    if (a < 0.0) std::reverse(v.begin(), v.end());
}

/** Thread-local buffers reused by every clip() call on this thread. */
struct ClipWorkspace {
    std::vector<std::array<double, 2>> subj;
    std::vector<std::array<double, 2>> clipv;
    std::vector<std::array<double, 2>> out;
    std::vector<std::array<double, 2>> in;
    std::vector<Point> result;
};

inline ClipWorkspace& get_clip_workspace() {
    thread_local ClipWorkspace ws;
    return ws;
}

/**
 * @brief Clip subject P by clip polygon Q (Sutherland-Hodgman).
 *
 * Computes P ∩ Q by walking Q edge-by-edge and keeping only the part of the
 * current subject that lies in the left half-plane of each Q edge (Q is CCW).
 *
 * @pre Q must be convex. P need not be; here both usually are.
 * @param P_verts Subject polygon (Epick points).
 * @param Q_verts Convex clip polygon (Epick points).
 * @return Const ref to thread-local CCW polygon (no closing duplicate), or
 *         empty if degenerate. Valid until the next clip() on this thread.
 *
 * Algorithm: convert to doubles, force both CCW, then for each edge a→b of Q:
 *   inside(pt) := signed area(a,b,pt) >= 0  (left of / on the edge).
 *   For each subject edge prev→cur, emit by case:
 *     | prev  | cur  | action                          |
 *     |-------|------|---------------------------------|
 *     | in    | in   | emit cur                        |
 *     | out   | in   | emit intersection, then cur     |  (entering)
 *     | in    | out  | emit intersection               |  (leaving)
 *     | out   | out  | emit nothing                    |
 *   Intersection is the linear lerp of prev→cur at the zero-crossing of side.
 *
 * Edge cases: |P|<3 or |Q|<3 → empty; after any edge |out|<3 → stop / empty;
 *             result with <3 verts → empty.
 */
inline const std::vector<Point>& clip(const std::vector<Point>& P_verts,
                                      const std::vector<Point>& Q_verts) {
    ClipWorkspace& ws = get_clip_workspace();

    const int n = static_cast<int>(P_verts.size());
    const int m = static_cast<int>(Q_verts.size());
    if (n < 3 || m < 3) { ws.result.clear(); return ws.result; }

    ws.subj.clear();
    ws.clipv.clear();
    ws.subj.reserve(n);
    ws.clipv.reserve(m);
    for (const auto& p : P_verts)
        ws.subj.push_back({CGAL::to_double(p.x()), CGAL::to_double(p.y())});
    for (const auto& q : Q_verts)
        ws.clipv.push_back({CGAL::to_double(q.x()), CGAL::to_double(q.y())});
    to_ccw(ws.subj);
    to_ccw(ws.clipv);

    // subj is not read after this; swap avoids copying the subject polygon.
    ws.out.swap(ws.subj);
    ws.in.clear();
    for (int e = 0; e < m && ws.out.size() >= 3; ++e) {
        const int e1 = (e + 1 == m) ? 0 : e + 1;
        const double ax = ws.clipv[e][0],  ay = ws.clipv[e][1];
        const double bx = ws.clipv[e1][0], by = ws.clipv[e1][1];
        const double ex = bx - ax, ey = by - ay;
        // side >= 0 => pt on/left of a→b => inside (Q is CCW).
        auto side = [&](const std::array<double, 2>& pt) {
            return ex * (pt[1] - ay) - ey * (pt[0] - ax);
        };
        ws.in.swap(ws.out);
        ws.out.clear();
        const int sz = static_cast<int>(ws.in.size());
        int prev = sz - 1;
        for (int i = 0; i < sz; ++i) {
            const auto& cur = ws.in[i];
            const auto& prv = ws.in[prev];
            prev = i;
            const double sc = side(cur), sp = side(prv);
            const bool cin = sc >= 0.0, pin = sp >= 0.0;
            if (cin) {
                if (!pin) {
                    // out → in: emit crossing, then cur
                    const double t = sp / (sp - sc);
                    ws.out.push_back({prv[0] + t * (cur[0] - prv[0]),
                                      prv[1] + t * (cur[1] - prv[1])});
                }
                // in → in (or after entering): emit cur
                ws.out.push_back(cur);
            } else if (pin) {
                // in → out: emit crossing only
                const double t = sp / (sp - sc);
                ws.out.push_back({prv[0] + t * (cur[0] - prv[0]),
                                  prv[1] + t * (cur[1] - prv[1])});
            }
            // out → out: emit nothing
        }
    }
    ws.result.clear();
    if (ws.out.size() < 3) return ws.result;

    ws.result.reserve(ws.out.size());
    for (const auto& p : ws.out) ws.result.emplace_back(p[0], p[1]);
    return ws.result;
}

