namespace sh_double {

using Vec2 = std::array<double, 2>;

// --- 2D vector primitives (match the usual math notation) -----------------
//
//   cross(u, v)  = u_x v_y - u_y v_x     (= signed parallelogram area)
//   orient(a,b,p) = cross(b-a, p-a)      (= 2 * signed area of triangle abp)
//
// For a CCW clip edge a→b, the closed left half-plane is { p | orient(a,b,p) >= 0 }.

inline Vec2 sub(const Vec2& u, const Vec2& v) {
    return {u[0] - v[0], u[1] - v[1]};
}

inline double cross(const Vec2& u, const Vec2& v) {
    return u[0] * v[1] - u[1] * v[0];
}

inline Vec2 lerp(const Vec2& p, const Vec2& q, double t) {
    return {p[0] + t * (q[0] - p[0]), p[1] + t * (q[1] - p[1])};
}

/** orient(a,b,p) = cross(b-a, p-a); >0 ⇒ p left of directed edge a→b. */
inline double orient(const Vec2& a, const Vec2& b, const Vec2& p) {
    return cross(sub(b, a), sub(p, a));
}

inline bool in_left_halfplane(const Vec2& a, const Vec2& b, const Vec2& p) {
    return orient(a, b, p) >= 0.0;
}

/**
 * Point where segment p→q meets the boundary line through a→b.
 * Requires orient(a,b,p) and orient(a,b,q) to have opposite signs (a crossing).
 * Solved from: (1-t)·orient_p + t·orient_q = 0  ⇒  t = orient_p / (orient_p - orient_q).
 */
inline Vec2 intersect_line(const Vec2& p, const Vec2& q,
                           double orient_p, double orient_q) {
    return lerp(p, q, orient_p / (orient_p - orient_q));
}

/**
 * @brief Orient polygon CCW in place (reverse if clockwise signed area < 0).
 *
 * Signed area = (1/2) Σ cross(v_i, v_{i+1}); sign alone decides orientation.
 */
inline void to_ccw(std::vector<Vec2>& v) {
    double twice_area = 0.0;
    const int n = static_cast<int>(v.size());
    for (int i = 0; i < n; ++i)
        twice_area += cross(v[i], v[(i + 1) % n]);
    if (twice_area < 0.0) std::reverse(v.begin(), v.end());
}

/**
 * Clip subject polygon S by the closed left half-plane of directed edge a→b.
 *
 * Walks each edge prev→cur of S and emits vertices by the SH case table:
 *   in→in: cur;  out→in: crossing then cur;  in→out: crossing;  out→out: nothing.
 * Complexity: O(|S|).
 */
inline void clip_by_halfplane(const std::vector<Vec2>& S,
                              const Vec2& a, const Vec2& b,
                              std::vector<Vec2>& out) {
    out.clear();
    const int n = static_cast<int>(S.size());
    if (n == 0) return;

    int prev_i = n - 1;
    for (int i = 0; i < n; ++i) {
        const Vec2& cur  = S[i];
        const Vec2& prev = S[prev_i];
        prev_i = i;

        const double o_cur  = orient(a, b, cur);
        const double o_prev = orient(a, b, prev);
        const bool cur_in   = o_cur  >= 0.0;
        const bool prev_in  = o_prev >= 0.0;

        if (cur_in) {
            if (!prev_in)
                out.push_back(intersect_line(prev, cur, o_prev, o_cur));  // entering
            out.push_back(cur);
        } else if (prev_in) {
            out.push_back(intersect_line(prev, cur, o_prev, o_cur));      // leaving
        }
    }
}

/** Thread-local buffers reused by every clip() call on this thread. */
struct ClipWorkspace {
    std::vector<Vec2> subj;
    std::vector<Vec2> clipv;
    std::vector<Vec2> out;
    std::vector<Vec2> in;
    std::vector<Point> result;
};

inline ClipWorkspace& get_clip_workspace() {
    thread_local ClipWorkspace ws;
    return ws;
}

/**
 * @brief Clip subject P by clip polygon Q (Sutherland-Hodgman).
 *
 * Q is the intersection of m left half-planes (one per edge). Starting from
 * S = P, replace S ← S ∩ H_e for each edge e of Q. Result is P ∩ Q.
 *
 * @pre Q must be convex (and is forced CCW). P need not be; here both usually are.
 * @return Const ref to thread-local CCW polygon (no closing duplicate), or
 *         empty if degenerate. Valid until the next clip() on this thread.
 *
 * Complexity: O(|P| · |Q|).
 */
inline const std::vector<Point>& clip(const std::vector<Point>& P_verts,
                                      const std::vector<Point>& Q_verts) {
    ClipWorkspace& ws = get_clip_workspace();

    const int n = static_cast<int>(P_verts.size());
    const int m = static_cast<int>(Q_verts.size());
    if (n < 3 || m < 3) { ws.result.clear(); return ws.result; }

    ws.subj.clear();
    ws.clipv.clear();
    ws.subj.reserve(n);
    ws.clipv.reserve(m);
    for (const auto& p : P_verts)
        ws.subj.push_back({CGAL::to_double(p.x()), CGAL::to_double(p.y())});
    for (const auto& q : Q_verts)
        ws.clipv.push_back({CGAL::to_double(q.x()), CGAL::to_double(q.y())});
    to_ccw(ws.subj);
    to_ccw(ws.clipv);

    // subj is not read after this; swap avoids copying the subject polygon.
    ws.out.swap(ws.subj);
    ws.in.clear();
    for (int e = 0; e < m && ws.out.size() >= 3; ++e) {
        const Vec2& a = ws.clipv[e];
        const Vec2& b = ws.clipv[(e + 1 == m) ? 0 : e + 1];
        ws.in.swap(ws.out);                       // in = current subject S
        clip_by_halfplane(ws.in, a, b, ws.out);   // out = S ∩ left_halfplane(a→b)
    }

    ws.result.clear();
    if (ws.out.size() < 3) return ws.result;

    ws.result.reserve(ws.out.size());
    for (const auto& p : ws.out) ws.result.emplace_back(p[0], p[1]);
    return ws.result;
}

